            if(!match($p['type']){'boolean'=>is_bool($v),'integer'=>is_int($v)&&$v>=$p['min']&&$v<=$p['max'],'string'=>is_string($v)&&strlen($v)<=$p['max']&&preg_match('//u',$v)&&!str_contains($v,"\0")&&(!isset($p['choices'])||in_array($v,$p['choices'],true))})self::invalid();$result[$n]=$v;}
        if(array_diff_key($values,$result))self::invalid();return $result;
